import{_ as i,o as t,c as e,ag as n}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"Vertical Slice: In-App Notifications & WebSockets","description":"","frontmatter":{},"headers":[],"relativePath":"en/11-inapp-notifications-websocket.md","filePath":"en/11-inapp-notifications-websocket.md"}'),s={name:"en/11-inapp-notifications-websocket.md"};function o(c,a,l,r,p,d){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="vertical-slice-in-app-notifications-websockets" tabindex="-1">Vertical Slice: In-App Notifications &amp; WebSockets <a class="header-anchor" href="#vertical-slice-in-app-notifications-websockets" aria-label="Permalink to &quot;Vertical Slice: In-App Notifications &amp; WebSockets&quot;">​</a></h1><blockquote><p><strong>Real-time full-duplex WebSocket notification stream, dynamic unread counters, and persistent history.</strong></p></blockquote><hr><h2 id="_1-architectural-overview" tabindex="-1">1. Architectural Overview <a class="header-anchor" href="#_1-architectural-overview" aria-label="Permalink to &quot;1. Architectural Overview&quot;">​</a></h2><p>The <code>notifications</code> slice (<code>apps/api/src/slices/notifications/</code>) manages real-time alerts and user messaging:</p><ul><li><strong>Full-Duplex WebSocket Channel:</strong> Authenticated WebSocket endpoint at <code>/api/v1/notifications/ws?token=...</code> delivering events instantly without polling overhead.</li><li><strong>Multi-Device Connection Manager:</strong> <code>NotificationConnectionManager</code> tracks open sockets per <code>user_id</code>, multiplexing frames to all active tabs or devices simultaneously.</li><li><strong>Liveness Ping/Pong:</strong> Responds to client <code>{&quot;type&quot;: &quot;ping&quot;}</code> heartbeats with <code>{&quot;type&quot;: &quot;pong&quot;}</code> to maintain long-lived connection health.</li><li><strong>Persistent History:</strong> Every notification is stored in PostgreSQL (<code>notifications</code> table) with read status and unread counters.</li><li><strong>Batch Operations:</strong> Supports single read updates (<code>PATCH /{id}/read</code>) and mass mark-as-read (<code>POST /mark-all-read</code>).</li></ul><hr><h2 id="_2-notification-flow-diagram" tabindex="-1">2. Notification Flow Diagram <a class="header-anchor" href="#_2-notification-flow-diagram" aria-label="Permalink to &quot;2. Notification Flow Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Client as Browser / Frontend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant WS as WebSocket Manager (/notifications/ws)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as FastAPI API (/notifications)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as notifications Table</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;WS: Connects via WebSocket (?token=JWT)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WS--&gt;&gt;Client: Connection Established</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Client,WS: Real-time channel active</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    par System Trigger (e.g. Invoice Paid, Project Created)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API-&gt;&gt;DB: Stores notification with is_read=False</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API-&gt;&gt;WS: ws_manager.send_personal_notification(user_id, payload)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        WS--&gt;&gt;Client: Emits JSON event frame in real time</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Client-&gt;&gt;Client: Increments bell badge &amp; displays Toast</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;API: PATCH /api/v1/notifications/{id}/read</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Marks is_read=True</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Client: HTTP 200 OK</span></span></code></pre></div><hr><h2 id="_3-endpoints" tabindex="-1">3. Endpoints <a class="header-anchor" href="#_3-endpoints" aria-label="Permalink to &quot;3. Endpoints&quot;">​</a></h2><h3 id="get-api-v1-notifications" tabindex="-1"><code>GET /api/v1/notifications</code> <a class="header-anchor" href="#get-api-v1-notifications" aria-label="Permalink to &quot;\`GET /api/v1/notifications\`&quot;">​</a></h3><p>Paginated notifications for the authenticated user.</p><ul><li><strong>Query Params:</strong> <code>unread_only</code>, <code>page</code>, <code>page_size</code>.</li></ul><h3 id="get-api-v1-notifications-unread-count" tabindex="-1"><code>GET /api/v1/notifications/unread-count</code> <a class="header-anchor" href="#get-api-v1-notifications-unread-count" aria-label="Permalink to &quot;\`GET /api/v1/notifications/unread-count\`&quot;">​</a></h3><p>Returns the badge counter (<code>unread_count</code>).</p><h3 id="patch-api-v1-notifications-notification-id-read" tabindex="-1"><code>PATCH /api/v1/notifications/{notification_id}/read</code> <a class="header-anchor" href="#patch-api-v1-notifications-notification-id-read" aria-label="Permalink to &quot;\`PATCH /api/v1/notifications/{notification_id}/read\`&quot;">​</a></h3><p>Marks a specific notification as read.</p><h3 id="post-api-v1-notifications-mark-all-read" tabindex="-1"><code>POST /api/v1/notifications/mark-all-read</code> <a class="header-anchor" href="#post-api-v1-notifications-mark-all-read" aria-label="Permalink to &quot;\`POST /api/v1/notifications/mark-all-read\`&quot;">​</a></h3><p>Marks all user notifications as read in a single batch.</p><h3 id="websocket-api-v1-notifications-ws" tabindex="-1"><code>WebSocket /api/v1/notifications/ws</code> <a class="header-anchor" href="#websocket-api-v1-notifications-ws" aria-label="Permalink to &quot;\`WebSocket /api/v1/notifications/ws\`&quot;">​</a></h3><p>Persistent full-duplex stream authenticated via <code>?token=&lt;access_token&gt;</code>.</p>`,22)])])}const g=i(s,[["render",o]]);export{k as __pageData,g as default};
